import type { SurveyLine } from '../types.ts';

/** Lines generated by one shrinkwrap preview session, including its cut aids. */
export function isShrinkwrapSessionLine(line: SurveyLine, polylineId: string): boolean {
  if (!polylineId) return false;
  return line.polylineId === polylineId
    || (line.polylineId || '').startsWith(`${polylineId}_cut_`);
}

/**
 * Clear a shrinkwrap preview without deleting geometry the user already
 * committed as an inclusion boundary. Inclusion lines are deliberately
 * detached from the preview lifecycle, even when they still carry the
 * session's polylineId for boundary grouping.
 */
export function clearShrinkwrapSessionLines(
  lines: SurveyLine[],
  polylineId: string,
): SurveyLine[] {
  return lines.filter(line =>
    line.type === 'inclusion' || !isShrinkwrapSessionLine(line, polylineId)
  );
}
